from pathlib import Path
import pandas as pd
RAIZ = Path(__file__).resolve().parents[1]
b0 = pd.read_csv(RAIZ / "resultados" / "referencias_f5_3.csv").iloc[0]
g2 = pd.read_csv(RAIZ / "resultados" / "top5_g2.csv").sort_values("mae_media")
f45 = pd.read_csv(RAIZ / "resultados" / "experimentos_f4_5.csv").sort_values("mae_media")
melhor_g2, campeao, vice = g2.iloc[0], f45.iloc[0], f45.iloc[1]
faixas = ["q1", "q2", "q3", "q4", "p99"]
modelos = [("Baseline (B0)", b0), ("Melhor G2 (" + str(melhor_g2["id"]) + ")", melhor_g2), ("Campeao G3 (" + str(campeao["desbalanceamento"]) + ")", campeao), ("Vice G3 (" + str(vice["desbalanceamento"]) + ")", vice)]
linhas_mae = [{"Modelo": n, "MAE": r["mae_media"], "RMSE": r["rmse_media"], "MAPE": r["mape_media"], "R2": r["r2_media"], **{f.upper() + "_MAE": r[f + "_mae_media"] for f in faixas}} for n, r in modelos]
linhas_vies = [{"Modelo": n, **{f.upper() + "_VIES": r[f + "_vies_media"] for f in faixas}} for n, r in modelos]
print("=== COMPARATIVO GATE G3 (METRICAS GLOBAIS E MAE POR FAIXA) ===")
print(pd.DataFrame(linhas_mae).round(4).to_string(index=False))
print("\n=== VIES POR FAIXA (R$) ===")
print(pd.DataFrame(linhas_vies).round(2).to_string(index=False))
linhas_tab = ["| " + str(i) + " | `" + str(r["id"]) + "` | " + str(r["faltantes"]) + " | " + str(r["escala"]) + " | " + str(r["ponderacao"]) + " | `" + str(r["desbalanceamento"]) + "` | R$ " + format(r["mae_media"], ",.2f") + " | R$ " + format(r["rmse_media"], ",.2f") + " | " + format(r["r2_media"], ".4f") + " | R$ " + format(r["q4_mae_media"], ",.2f") + " | R$ " + format(r["p99_mae_media"], ",.2f") + " |" for i, (_, r) in enumerate(f45.head(5).iterrows(), 1)]
md = "\n".join(["# Gate G3 - Estagio 3 (F4-5: Desbalanceamento no Top-5)", "", "**Data:** 25/11/2026", "**Protocolo:** cruzamento das 5 configuracoes congeladas no Gate G2 (`resultados/top5_g2.csv`) com as 4 tecnicas de reamostragem aprovadas no Gate G1 (`random_over`, `random_under`, `gaussian_noise`, `smoter`), aplicadas exclusivamente no treino de cada fold (`KFold(10, shuffle=True, random_state=42)`), alvo em `log1p` e avaliacao na escala original.", "", "## Execucao", "", "Os 20 experimentos (`5 pipelines x 4 tecnicas`) foram executados via `python src/rodar_f4_5.py` e salvos em `resultados/experimentos_f4_5.csv`. O metodo `SMOGN` foi mantido fora da grade conforme decisao do Gate G1 devido ao custo computacional inviavel.", "", "## Resultados consolidados (Top-5 do Estagio 3)", "", "| Posicao | ID | Faltantes | Escala | Ponderacao | Desbalanceamento | MAE medio | RMSE medio | R2 medio | Q4 MAE | P99 MAE |", "|---:|---|---|---|---|---|---:|---:|---:|---:|---:|", *linhas_tab, "", "## Selecao do modelo campeao (Gate G3)", "", "- **Campeao oficial (`" + str(campeao["id"]) + "`):** `" + str(campeao["faltantes"]) + "` + `" + str(campeao["encoding"]) + "` + `" + str(campeao["escala"]) + "` + `" + str(campeao["ponderacao"]) + "` + `" + str(campeao["desbalanceamento"]) + "`.", "- **Desempenho global:** MAE = **R$ " + format(campeao["mae_media"], ",.2f") + "** (-R$ " + format(melhor_g2["mae_media"] - campeao["mae_media"], ",.2f") + " vs melhor G2; -R$ " + format(b0["mae_media"] - campeao["mae_media"], ",.2f") + " vs baseline B0) e R2 = **" + format(campeao["r2_media"], ".4f") + "**.", "- **Cauda direita (imoveis caros):** Q4 MAE caiu de R$ " + format(melhor_g2["q4_mae_media"], ",.2f") + " para **R$ " + format(campeao["q4_mae_media"], ",.2f") + "** (-R$ " + format(melhor_g2["q4_mae_media"] - campeao["q4_mae_media"], ",.2f") + ") e P99 MAE caiu de R$ " + format(melhor_g2["p99_mae_media"], ",.2f") + " para **R$ " + format(campeao["p99_mae_media"], ",.2f") + "** (-R$ " + format(melhor_g2["p99_mae_media"] - campeao["p99_mae_media"], ",.2f") + ").", "- **Vice-campeao (`" + str(vice["id"]) + "` - `" + str(vice["desbalanceamento"]) + "`):** MAE = R$ " + format(vice["mae_media"], ",.2f") + ", maior R2 (**" + format(vice["r2_media"], ".4f") + "**) e menor P99 MAE (**R$ " + format(vice["p99_mae_media"], ",.2f") + "**).", "- **Descarte de `random_under`:** degradou o MAE em todos os cenarios (R$ 166,9 mil a R$ 169,6 mil).", "", "## Encaminhamento para Etapa 4 (F5-6)", "", "- Incluir `resultados/experimentos_f4_5.csv` em `src/analise_f5.py` para consolidar os 202 experimentos unicos, rodar o teste de Wilcoxon por fold e congelar as tabelas e graficos finais."])
(RAIZ / "Docs" / "gate_g3.md").write_text(md, encoding="utf-8")
